import json

# Try completing each row by repeating its own pattern
output_grid = [[c for c in row] for row in input_grid]

def complete_row(row):
    """Complete row by repeating until we find a pattern match"""
    result = list(row)

    # Find the period by checking small periods
    for period in range(1, len(result)//2 + 1):
        matches = True
        for i in range(len(result)):
            if result[i % period] != result[i]:
                matches = False
                break
        if matches:
            return result

    # If no full period found, repeat the last N columns
    last_nonzero_idx = max((i for i, v in enumerate(result) if v != 0), default=0)
    if last_nonzero_idx > 0:
        pattern = result[:last_nonzero_idx+1]
        for col in range(len(result)):
            result[col] = pattern[col % len(pattern)]

    return result

for i in [14, 15, 16, 17]:
    output_grid[i] = complete_row(output_grid[i])

print("Pattern repeat completion:")
for i in [14, 15, 16, 17]:
    print(f"Row {i}: {output_grid[i]}")

print(json.dumps({"action": "submit", "grid": output_grid}))
